    for index in range(len(nums)-2,-1,-1):suffix=min(nums[index],suffix);suffix_min[index]=suffix
    prefix=0;answer=-10**30
    for index in range(len(nums)-1):prefix+=nums[index];answer=max(answer,prefix-suffix_min[index+1])
    return answer

